from collections import deque


class PrivateLotStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = [
            self.AddEquity("SPY", Resolution.Daily).Symbol,
            self.AddEquity("AAPL", Resolution.Daily).Symbol,
            self.AddEquity("IBM", Resolution.Daily).Symbol,
            self.AddEquity("BAC", Resolution.Daily).Symbol,
            self.AddEquity("AIG", Resolution.Daily).Symbol
        ]

        self.spy = self.Symbol("SPY")
        self.aapl = self.Symbol("AAPL")

        self.spy_closes = deque(maxlen=101)

        self.aapl_close_count = 0
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.rsi_period = 14
        self.rsi_initial_gains = []
        self.rsi_initial_losses = []
        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.aapl_rsi = None
        self.aapl_rsi_ready = False

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data):
        bars = {}

        for symbol in self.symbols:
            if data.Bars.ContainsKey(symbol):
                bars[symbol] = data.Bars[symbol]

        if self.spy in bars:
            self.spy_closes.append(bars[self.spy].Close)

        if self.aapl in bars:
            self._update_aapl_state(bars[self.aapl].Close)

        # Rule evaluation is skipped unless every subscribed ticker has a bar.
        if len(bars) != len(self.symbols):
            return

        spy_close = bars[self.spy].Close
        aapl_close = bars[self.aapl].Close

        spy_crosses_above = False
        spy_crosses_below = False

        if len(self.spy_closes) == 101:
            closes = list(self.spy_closes)
            yesterday_sma = sum(closes[:-1]) / 100.0
            today_sma = sum(closes[-100:]) / 100.0

            spy_crosses_above = (
                closes[-2] <= yesterday_sma and closes[-1] > today_sma
            )
            spy_crosses_below = (
                closes[-2] >= yesterday_sma and closes[-1] < today_sma
            )

        strategy_b_buy_ready = (
            self.aapl_close_count >= 4 and self.aapl_red_streak >= 3
        )
        strategy_b_sell_ready = (
            self.aapl_rsi_ready and self.aapl_rsi is not None and self.aapl_rsi > 60
        )

        # Sells are evaluated before buys.
        if self.strategy_a_lot > 0 and spy_crosses_below:
            self.MarketOrder(self.spy, -self.strategy_a_lot, "Strategy A sell")
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and strategy_b_sell_ready:
            self.MarketOrder(self.aapl, -self.strategy_b_lot, "Strategy B sell")
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and spy_crosses_above:
            shares = int((self.Portfolio.TotalPortfolioValue * 0.40) / spy_close)
            if shares > 0:
                self.MarketOrder(self.spy, shares, "Strategy A buy")
                self.strategy_a_lot = shares

        if self.strategy_b_lot == 0 and strategy_b_buy_ready:
            if self.Portfolio.Cash >= 20_000:
                shares = int(20_000 / aapl_close)
                if shares > 0:
                    self.MarketOrder(self.aapl, shares, "Strategy B buy")
                    self.strategy_b_lot = shares

    def _update_aapl_state(self, close):
        self.aapl_close_count += 1

        if self.aapl_previous_close is not None:
            if close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            change = close - self.aapl_previous_close
            gain = max(change, 0)
            loss = max(-change, 0)

            if not self.aapl_rsi_ready:
                self.rsi_initial_gains.append(gain)
                self.rsi_initial_losses.append(loss)

                if len(self.rsi_initial_gains) == self.rsi_period:
                    self.rsi_average_gain = (
                        sum(self.rsi_initial_gains) / self.rsi_period
                    )
                    self.rsi_average_loss = (
                        sum(self.rsi_initial_losses) / self.rsi_period
                    )
                    self.aapl_rsi_ready = True
                    self.aapl_rsi = self._rsi_value()
            else:
                self.rsi_average_gain = (
                    (self.rsi_average_gain * (self.rsi_period - 1) + gain)
                    / self.rsi_period
                )
                self.rsi_average_loss = (
                    (self.rsi_average_loss * (self.rsi_period - 1) + loss)
                    / self.rsi_period
                )
                self.aapl_rsi = self._rsi_value()

        self.aapl_previous_close = close

    def _rsi_value(self):
        if self.rsi_average_loss == 0:
            return 100.0

        relative_strength = self.rsi_average_gain / self.rsi_average_loss
        return 100.0 - (100.0 / (1.0 + relative_strength))
